import rateLimit from 'express-rate-limit';
import express from 'express';
import path from 'path';
import { createServer as createViteServer } from 'vite';
import { GoogleGenAI } from '@google/genai';

const app = express();
app.set('trust proxy', 1);
const PORT = 3000;

// Middleware to parse requests
app.use(express.json());
    
// Add CORS
app.use((req, res, next) => {
  const origin = req.headers.origin;
  const allowedOrigins = ['http://localhost:3000', 'capacitor://localhost', 'http://localhost'];
  if (allowedOrigins.includes(origin as string) || process.env.NODE_ENV !== 'production') {
    res.header('Access-Control-Allow-Origin', origin || '*');
  } else {
    res.header('Access-Control-Allow-Origin', '*');
  }
  res.header('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
  res.header('Access-Control-Allow-Headers', 'Content-Type, Authorization');
  if (req.method === 'OPTIONS') return res.sendStatus(200);
  next();
});

const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  message: { error: 'Too many requests, please try again later.' },
  validate: { xForwardedForHeader: false, trustProxy: false, default: false }
});

app.use('/api/', apiLimiter);

// Initialize the Gemini AI client
const geminiApiKey = process.env.GEMINI_API_KEY;
let ai: GoogleGenAI | null = null;
if (geminiApiKey && typeof geminiApiKey === 'string' && geminiApiKey.trim().length > 0) {
  try {
    ai = new GoogleGenAI({ apiKey: geminiApiKey });
  } catch (e) {
    console.error("Failed to initialize GoogleGenAI");
  }
}

function generateStaticFeedback(hours: number, sleep: number, screenTime: number) {
  if (hours >= 8) {
    if (sleep < 6) return `Elite execution logging ${hours} hours. But 10hrs + 4hrs sleep = 4hrs real learning. Sleep IS the study. Get 7+ tonight.\n\n🔒 Lock: Stop mistaking exhaustion for effectiveness.`;
    return `Elite day yesterday. Acknowledge it, then drop it. The ego hangover will kill today's momentum. Plan your first 30 mins.\n\n🔒 Lock: Best day yet means nothing. Reset now.`;
  } else if (hours >= 4) {
    if (screenTime > 4) return `Solid day, but you're burning dopamine to avoid friction (${screenTime}h screens). Phone out of the room. Win the first 30 minutes.\n\n🔒 Lock: Not lazy. Dopamine-hacked. Break the pattern.`;
    return `Solid consistency with ${hours} hours. Your 12-hour plan is anxiety, not strategy. Add exactly one 90-minute block today. Earn the right to 8 hours.\n\n🔒 Lock: Compound beats explosive every time.`;
  } else {
    return `Let's stop the guilt spiral. Phone out. Give me one 25-minute focus sprint on a single DPP. Reclaim your identity as someone who grinds through discomfort.\n\n🔒 Lock: Zero-day is just data. Break the inertia.`;
  }
}

// API router - AI Coach
app.post('/api/ai-coach', async (req, res) => {
  const { hours, sleep, screenTime, completedTasksCount, plannedTasksCount, history } = req.body;

  // STEP 2: RUN THE GAP SCAN
  const complianceScore = Math.round(((completedTasksCount || 0) / Math.max(1, plannedTasksCount || 1)) * 100);
  
  let flags: string[] = [];
  if (hours > 4 && completedTasksCount === 0) flags.push("fake_work");
  if (sleep < 6) flags.push("sleep_debt");
  if (screenTime > 4 && hours < 4) flags.push("dopamine_drift");
  
  // STEP 3: DETECT PATTERNS
  if (Array.isArray(history)) {
    const recentMisses = history.filter(h => h.isMissed || h.hoursStudied < 2).length;
    if (recentMisses >= 3) flags.push("streak_broken_trend");
  }

  // STEP 4: COMPUTE SEVERITY SCORE
  let severity = 5;
  if (sleep >= 7) severity -= 1;
  if (screenTime < 2) severity -= 1;
  if (complianceScore >= 80) severity -= 1;
  
  if (sleep < 6) severity += 1;
  if (screenTime > 4) severity += 1;
  if (complianceScore < 50) severity += 1;
  if (flags.includes("fake_work")) severity += 2;
  if (flags.includes("streak_broken_trend")) severity += 1;
  
  severity = Math.max(1, Math.min(10, severity));

  let label = "";
  if (severity <= 2) label = "Elite";
  else if (severity <= 4) label = "Consistent";
  else if (severity <= 6) label = "Off Track";
  else if (severity <= 8) label = "Warning: Crash/Burnout";
  else label = "Total Breakdown";

  // Paragraph 1: Cold Opening
  const p1 = `Yesterday’s raw report: Sleep ${sleep}h. Screen ${screenTime}h. You did ${hours}h of study. Tasks: ${completedTasksCount}/${plannedTasksCount}.`;

  // Paragraph 2: Gap & Wound Statement
  let p2 = "Clean execution.";
  if (flags.includes("fake_work")) p2 = `${hours}h at desk and barely any output. That’s passive consumption, not training.`;
  else if (flags.includes("dopamine_drift")) p2 = `You burnt your dopamine avoiding friction with ${screenTime}h on screens.`;
  else if (flags.includes("sleep_debt")) p2 = "Sleep debt is destroying your retention.";
  else if (flags.includes("streak_broken_trend")) p2 = "You are breaking your promises consistently. The trend is downward.";

  // Paragraph 3: Severity-Based Escalation Phrase
  let p3 = "";
  if (severity <= 2) p3 = "Elite output. Maintain rhythm.";
  else if (severity <= 4) p3 = "Consistent. Don't let off the gas.";
  else if (severity <= 6) p3 = "You’re drifting. Wake up.";
  else if (severity <= 8) p3 = "This is self-sabotage dressed as effort.";
  else p3 = "You’re handing your IIT seat to someone who fixes their faults faster.";

  // Paragraph 4: Prescribe Daily Mission
  let p4 = "";
  if (flags.includes("fake_work")) p4 = "Today, track only output. Any study hour without output doesn’t count.";
  else if (flags.includes("sleep_debt")) p4 = "Target 6h of sharp work. No more. Sleep 7.5h tonight mandatory. Recovery is the mission.";
  else if (flags.includes("dopamine_drift")) p4 = "Phone locked outside room until first 90-min block complete.";
  else p4 = "Sustain rhythm: deep work with one 90-min block on your weakest topic.";

  // Paragraph 5: The Goggins Push
  const pushes = ["Stay hard.", "The mirror is the only enemy you must beat today.", "Go to war with yourself. I'm watching."];
  const p5 = pushes[Math.floor(Math.random() * pushes.length)];

  const fallbackResponse = `${p1}\n\n${p2}\n\n${p3}\n\n${p4}\n\n${p5}`;

  // If we don't have an AI client, immediately return our pure logic engine result.
  if (!ai) {
    console.warn("GEMINI_API_KEY is not defined. Using pure logic engine.");
    return res.json({ feedback: fallbackResponse });
  }

  // Return the pure logic engine result (as requested, this produces a better, more predictable output than generic AI)
  return res.json({ feedback: fallbackResponse });
});

app.post("/api/dynamic-insight", async (req, res) => {
  const { hoursToday, streak, accuracy, questionsSolved, target, pendingTasksCount, recentTaskTypes } = req.body;

  let insight = "Hours don't crack JEE. Output does. Hunt weaknesses and track problems solved.";

  const hrs = hoursToday || 0;
  const acc = accuracy || 0;
  const q = questionsSolved || 0;
  const tgt = target || 0;

  if (hrs < 2 && pendingTasksCount > 0) {
    insight = "You didn't fail willpower; you failed environmental design. Phone in another room. Win the next 30 minutes.\n\n🔒 Lock: Motion beats stagnation. Break the pattern.";
  } else if (hrs > 4 && q < 15) {
    insight = "Reading theory is hiding from failure. Close the book. Give me one 25-minute problem sprint.\n\n🔒 Lock: Fake productivity alert. Chase friction.";
  } else if (acc < 60 && q > 10) {
    insight = "You are recognizing theory, not recalling concepts. Read less. Solve more.\n\n🔒 Lock: Your error rate is bleeding out gains. Accuracy > Speed today.";
  } else if (q >= tgt && tgt > 0) {
    insight = "Elite execution. You put up numbers today. Now drop it. The ego hangover will kill tomorrow's momentum.\n\n🔒 Lock: Targets hit. Acknowledge it, then drop it.";
  } else if (streak >= 3) {
    insight = `Discipline is boring replication. The top 100 ranks aren't built on motivation.\n\n🔒 Lock: Protect the ${streak}-day streak. Return fast.`;
  }

  return res.json({ insight });
});

async function startServer() {
  // Vite development middleware vs Static file server
  if (process.env.NODE_ENV !== 'production' && !process.env.VERCEL) {
    const vite = await createViteServer({
      server: { middlewareMode: true },
      appType: 'spa',
    });
    app.use(vite.middlewares);
  } else if (!process.env.VERCEL) {
    const distPath = path.join(process.cwd(), 'dist');
    app.use(express.static(distPath));
    app.get('*', (req, res) => {
      res.sendFile(path.join(distPath, 'index.html'));
    });
  }

  if (!process.env.VERCEL) {
    app.listen(PORT, '0.0.0.0', () => {
      console.log(`Server running on http://localhost:${PORT}`);
    });
  }
}

startServer();

export default app;
